import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";

export default function Candidates() {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await api.get("/candidates");
        setCandidates(res.data);
      } catch (err) {
        setError(err.response?.data?.error || "Failed to load candidates");
      } finally {
        setLoading(false);
      }
    };
    fetchCandidates();
  }, []);

  if (loading)
    return <p className="text-center mt-10 text-gray-600">Loading candidates...</p>;
  if (error) return <p className="text-center mt-10 text-red-600">{error}</p>;

  return (
    <div className="min-h-screen bg-gray-50 px-6 py-10">
      {/* Page header */}
      <div className="max-w-6xl mx-auto mb-8 text-center">
        <h1 className="text-3xl font-bold text-gray-800">Election Candidates</h1>
        <p className="text-gray-600 text-lg">
          Review the list of approved candidates before casting your vote.
        </p>
      </div>

      {/* Candidate grid */}
      <div className="max-w-6xl mx-auto grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {candidates.map((c) => (
          <div
            key={c.id}
            className="bg-white border border-gray-200 shadow-sm rounded-2xl p-6 flex flex-col items-center hover:shadow-md transition"
          >
            {/* Candidate avatar */}
            <div className="w-20 h-20 flex items-center justify-center rounded-full bg-blue-100 text-blue-700 font-bold text-xl mb-4">
              {c.name.charAt(0)}
            </div>

            {/* Candidate details */}
            <h2 className="text-xl font-semibold text-gray-800">{c.name}</h2>
            <p className="text-gray-600 mb-3">{c.position}</p>
            {c.manifesto && (
              <p className="text-sm text-gray-500 text-center line-clamp-3">
                {c.manifesto}
              </p>
            )}

            {/* Vote button */}
            <button
              onClick={() => navigate("/vote", { state: { candidate: c } })}
              className="mt-5 bg-blue-600 text-white px-5 py-2 rounded-xl hover:bg-blue-700 transition"
            >
              Vote
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
